/* ── Auto-trade section ─────────────────────────────── */
.dash-auto-trade {
  border: 1px solid var(--line);
  padding: 1.5rem;
  margin-top: 1.5rem;
}

.auto-trade-badge {
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  padding: 0.2rem 0.5rem;
  border-radius: 2px;
}

.auto-trade-badge--on {
  background: rgba(46, 203, 113, 0.15);
  color: #2ecb71;
  border: 1px solid rgba(46, 203, 113, 0.3);
}

.auto-trade-badge--off {
  background: rgba(154, 154, 151, 0.1);
  color: var(--muted);
  border: 1px solid var(--line);
}

.auto-trade-form {
  margin-top: 1.25rem;
  display: flex;
