/* ── Auto-trade section ─────────────────────────────── */
.dash-auto-trade {
  border: 1px solid var(--line);
  padding: 1.5rem;
  margin-top: 1.5rem;
}

.auto-trade-badge {
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  padding: 0.2rem 0.5rem;
  border-radius: 2px;
}

.auto-trade-badge--on {
  background: rgba(46, 203, 113, 0.15);
  color: #2ecb71;
  border: 1px solid rgba(46, 203, 113, 0.3);
}

.auto-trade-badge--off {
  background: rgba(154, 154, 151, 0.1);
  color: var(--muted);
  border: 1px solid var(--line);
}

.auto-trade-form {
  margin-top: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.auto-trade-toggle-row {
  display: flex;
  gap: 2rem;
  align-items: center;
  flex-wrap: wrap;
}

.auto-trade-head-right {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.auto-trade-global-mode {
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--muted);
  border: 1px solid var(--line);
  padding: 0.2rem 0.5rem;
  border-radius: 2px;
}

.auto-trade-mode-select {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.auto-trade-mode-warn {
  font-size: 0.7rem;
  color: #e04040;
  margin: 0.25rem 0 0;
}

.auto-trade-mode-hint {
  font-size: 0.7rem;
  color: var(--muted);
  margin: 0.25rem 0 0;
}

.auto-trade-mode-btns {
  display: flex;
  gap: 0;
}

.auto-trade-mode-btn {
  background: var(--soft);
  border: 1px solid var(--line);
  color: var(--muted);
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  padding: 0.35rem 0.75rem;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
  margin-left: -1px;
}

.auto-trade-mode-btn:first-child { border-radius: 2px 0 0 2px; }
.auto-trade-mode-btn:last-child  { border-radius: 0 2px 2px 0; }

.auto-trade-mode-btn.active {
  background: rgba(46, 203, 113, 0.15);
  color: #2ecb71;
  border-color: rgba(46, 203, 113, 0.4);
  z-index: 1;
}

.auto-trade-mode-btn.danger.active {
  background: rgba(224, 64, 64, 0.12);
  color: #e04040;
  border-color: rgba(224, 64, 64, 0.35);
}

.auto-trade-mode-btn:hover:not(.active) {
  background: var(--line);
  color: var(--ink);
}

.auto-trade-toggle {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  cursor: pointer;
  user-select: none;
}

.auto-trade-toggle input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.auto-trade-toggle__track {
  display: inline-block;
