}
.at-symbol-row__name { width: 4rem; flex-shrink: 0; font-weight: 700; color: var(--ink); }
.at-symbol-row__bar-wrap { flex: 1; height: 3px; background: var(--line); border-radius: 2px; overflow: hidden; }
