.at-mode-btn__dot { width: 6px; height: 6px; border-radius: 50%; flex-shrink: 0; }
.at-mode-btn__dot--demo { background: #60a5fa; }
.at-mode-btn__dot--live { background: #2ecb71; }

.at-warn {
  font-size: 0.72rem;
  color: #e04040;
  margin: 0;
  padding: 0.5rem 0.75rem;
  border: 1px solid rgba(224,64,64,0.2);
  background: rgba(224,64,64,0.05);
  border-radius: 2px;
}

.at-params-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
}

.at-param {
