  flex-direction: column;
  gap: 0.3rem;
}

.at-param__label {
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--muted);
}

.at-param__input-wrap {
  display: flex;
  align-items: center;
  border: 1px solid var(--line);
  background: var(--soft);
  overflow: hidden;
}

.at-param__input-wrap input {
  flex: 1;
  background: none;
  border: none;
  outline: none;
  color: var(--ink);
  font-size: 0.85rem;
  padding: 0.4rem 0.6rem;
  min-width: 0;
  font-family: inherit;
}

.at-param__unit {
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--muted);
  padding: 0 0.5rem;
  flex-shrink: 0;
  border-left: 1px solid var(--line);
}

.at-rr-pill {
  font-size: 0.68rem;
  font-weight: 700;
  color: var(--muted);
  padding: 0.3rem 0.65rem;
