  background: var(--soft);
  border-radius: 2px;
  display: inline-block;
  letter-spacing: 0.04em;
}

.at-symbols-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.at-chip {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  background: var(--soft);
  border: 1px solid var(--line);
  padding: 0.25rem 0.5rem 0.25rem 0.65rem;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--ink);
