file.content:
/* Signals table */

.signals-table-wrap,
.positions-table-wrap {
  overflow-x: auto;
  border: 1px solid var(--line);
}

.signals-table,
.positions-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}

.signals-table th,
.positions-table th {
  padding: 0.85rem 1rem;
  border-bottom: 1px solid var(--line);
  background: var(--soft);
  color: var(--muted);
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  text-align: left;
  white-space: nowrap;
}

.signals-table td,
.positions-table td {
  padding: 0.85rem 1rem;
  border-bottom: 1px solid var(--line);
  vertical-align: top;
}

.signals-table tbody tr:hover,
.positions-table tbody tr:hover {
  background: var(--soft);
}

.signal-rank {
  color: var(--muted);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 0.85rem;
  font-weight: 500;
  text-align: center;
  width: 2rem;
}

.signal-ticker {
  font-weight: 700;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.signal-action {
  display: inline-block;
  padding: 0.2rem 0.55rem;
  border-radius: 3px;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.signal-action--buy {
  background: rgba(46, 203, 113, 0.12);
  color: #2ecb71;
}

.signal-action--sell {
  background: rgba(224, 64, 64, 0.12);
  color: #e04040;
}

.signal-action--hold {
  background: rgba(255, 255, 255, 0.06);
  color: var(--muted);
}

.signal-confidence {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  min-width: 80px;
}

.signal-confidence__bar {
  display: block;
  height: 4px;
  border-radius: 2px;
  background: var(--ink);
  opacity: 0.6;
  flex-shrink: 0;
}

.signal-confidence__label {
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--muted);
  white-space: nowrap;
}

.signal-rationale {
  max-width: 36ch;
  color: var(--muted);
  font-size: 0.85rem;
  line-height: 1.5;
}

.signal-time {
  color: var(--muted);
  font-size: 0.82rem;
  white-space: nowrap;
}

/* Signal cards (mobile) */

.sig-mobile {
  display: none;
}

.sig-cards {
  flex-direction: column;
  gap: 1px;
  border: 1px solid var(--line);
  background: var(--line);
}

.sig-card {
  display: flex;
  flex-direction: column;
  background: var(--paper);
}

.sig-card__head {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.7rem 0.75rem 0.4rem;
}

.sig-card__rank {
  color: var(--muted);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 0.82rem;
  font-weight: 500;
  min-width: 1.2rem;
}

.sig-card__ticker {
  font-weight: 700;
  font-size: 0.88rem;
  letter-spacing: 0.02em;
}

.sig-card__conf {
  margin-left: auto;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--muted);
}

.sig-card__bar {
  height: 3px;
  margin: 0 0.75rem;
  background: var(--line);
}

.sig-card__bar-fill {
  display: block;
  height: 100%;
  background: var(--ink);
  opacity: 0.5;
}

.sig-card__rationale {
  margin: 0;
  padding: 0.3rem 0.75rem 0.65rem;
  color: var(--muted);
  font-size: 0.78rem;
  line-height: 1.45;
}

/* Signals pager */

.signals-pager {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1px;
  border: 1px solid var(--line);
  border-top: none;
  background: var(--line);
}

.pager-btn {
  flex: 0 0 auto;
  padding: 0.65rem 1.2rem;
  border: none;
  background: var(--paper);
  color: var(--muted);
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
  transition: color 0.15s, background 0.15s;
}

.pager-btn:hover:not(:disabled) {
  color: var(--ink);
  background: var(--soft);
}

.pager-btn:disabled {
  opacity: 0.25;
  cursor: not-allowed;
}

.pager-info {
  flex: 1;
  padding: 0.65rem 0;
  background: var(--paper);
  color: var(--muted);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.04em;

