/* Positions table — keep unchanged */
.positions-table-wrap {
  overflow-x: auto;
  border: 1px solid var(--line);
}

.positions-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}

.positions-table th {
  padding: 0.85rem 1rem;
  border-bottom: 1px solid var(--line);
  background: var(--soft);
  color: var(--muted);
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  text-align: left;
  white-space: nowrap;
}

.positions-table td {
  padding: 0.85rem 1rem;
  border-bottom: 1px solid var(--line);
  vertical-align: top;
}

.positions-table tbody tr:hover {
  background: var(--soft);
}

/* ── Signal entries (unified desktop + mobile) ─── */
.sig-list {
  border: 1px solid var(--line);
  display: flex;
  flex-direction: column;
}

.sig-entry {
  display: grid;
  grid-template-columns: 56px 1fr 68px;
  gap: 0;
  border-bottom: 1px solid var(--line);
  padding: 0.85rem 1rem 0.85rem 0.75rem;
  transition: background 0.12s;
}
.sig-entry:last-child { border-bottom: none; }
.sig-entry:hover { background: var(--soft); }

.sig-entry--buy  { border-left: 2px solid rgba(46,203,113,0.5); }
.sig-entry--sell { border-left: 2px solid rgba(224,64,64,0.4); }

/* Left column */
.sig-entry__left {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 0.4rem;
  padding-top: 0.1rem;
}

.sig-entry__rank {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--muted);
  font-family: Georgia, serif;
}

.sig-entry__badge {
  display: inline-block;
  padding: 0.2rem 0.45rem;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-radius: 2px;
}
.sig-entry__badge--buy  { background: rgba(46,203,113,0.12); color: #2ecb71; }
.sig-entry__badge--sell { background: rgba(224,64,64,0.12);  color: #e04040; }
.sig-entry__badge--hold { background: rgba(255,255,255,0.06); color: var(--muted); }

/* Center body */
.sig-entry__body {
  padding: 0 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  min-width: 0;
}

.sig-entry__top {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.sig-entry__ticker {
  font-family: Georgia, serif;
  font-size: 1.05rem;
  font-weight: 400;
  color: var(--ink);
  letter-spacing: -0.01em;
  flex-shrink: 0;
}

.sig-entry__symbol-full {
  font-size: 0.65rem;
  font-weight: 600;
  color: var(--muted);
  letter-spacing: 0.04em;
  flex-shrink: 0;
}

.sig-entry__headline {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--ink);
  line-height: 1.4;
}

.sig-entry__pills {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
}

.sig-pill {
  display: inline-block;
  font-size: 0.68rem;
  font-weight: 500;
  padding: 0.15rem 0.45rem;
  border: 1px solid var(--line);
  background: var(--soft);
  color: var(--muted);
  border-radius: 2px;
  line-height: 1.4;
}
.sig-pill--pos { color: #2ecb71; border-color: rgba(46,203,113,0.2); background: rgba(46,203,113,0.06); }
.sig-pill--neg { color: #e04040; border-color: rgba(224,64,64,0.2); background: rgba(224,64,64,0.04); }

/* Right column */
.sig-entry__right {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 0.3rem;
}

.sig-entry__conf {
  position: relative;
  width: 42px;
  height: 42px;
  flex-shrink: 0;
}

.sig-entry__arc {
  width: 42px;
  height: 42px;
  transform: rotate(0deg);
}

.sig-entry__conf-val {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.68rem;
  font-weight: 800;
  color: var(--ink);
  letter-spacing: -0.02em;
}

.sig-entry__time {
  font-size: 0.62rem;
  color: var(--muted);
  font-weight: 500;
  text-align: center;
  white-space: nowrap;
}

/* keep signal-action for other places that use it */
.signal-action {
  display: inline-block;
  padding: 0.2rem 0.55rem;
  border-radius: 3px;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.signal-action--buy  { background: rgba(46,203,113,0.12); color: #2ecb71; }
.signal-action--sell { background: rgba(224,64,64,0.12);  color: #e04040; }
.signal-action--hold { background: rgba(255,255,255,0.06); color: var(--muted); }
.signal-ticker { font-weight: 700; letter-spacing: 0.02em; white-space: nowrap; }

