{/* Solana (Drift) wallet connection */}
<div className="sol-connect">
  <div className="sol-connect__header">
    <div className="sol-connect__title-row">
      <svg className="sol-connect__logo" viewBox="0 0 24 24" width="18" height="18"><path fill="#9945ff" d="M20.5 16.2l-2.8 2.9c-.1.1-.3.2-.5.2H3.7c-.4 0-.6-.5-.3-.8l2.8-2.9c.1-.1.3-.2.5-.2H20.2c.4 0 .6.5.3.8zm-2.8-5.1c-.1-.1-.3-.2-.5-.2H3.7c-.4 0-.6.5-.3.8l2.8 2.9c.1.1.3.2.5.2H20.2c.4 0 .6-.5.3-.8l-2.8-2.9zM3.7 7.8h13.5c.2 0 .4.1.5.2l2.8 2.9c.3.3.1.8-.3.8H6.7c-.2 0-.4-.1-.5-.2L3.4 8.6c-.3-.3-.1-.8.3-.8z"/></svg>
      <span className="sol-connect__title">Drift Protocol</span>
      <span className="sol-connect__badge">On-chain</span>
    </div>
    {autoConfig?.has_solana_keys && (
      <span className="sol-connect__connected">Connected</span>
    )}
  </div>

  {autoConfig?.has_solana_keys && !showSolanaForm ? (
    <div className="sol-connect__active">
      <p className="sol-connect__active-msg">Wallet connected — trades execute on Drift Protocol (Solana mainnet, non-custodial).</p>
      <div className="sol-connect__active-actions">
        <button type="button" className="api-keys-btn" onClick={() => { setShowSolanaForm(true); setSolanaWizardStep(1); setSolanaPubkeyPreview(null); }}>Change wallet</button>
        <button type="button" className="api-keys-btn api-keys-btn--danger" onClick={handleRemoveSolanaKeys}>Disconnect</button>
      </div>
    </div>
  ) : !showSolanaForm ? (
    <div className="sol-connect__cta">
      <p className="sol-connect__desc">Connect a Solana wallet to auto-trade on Drift — a decentralised perps DEX. Your private key is encrypted at rest and never leaves the server.</p>
      <button type="button" className="sol-connect__btn" onClick={() => { setShowSolanaForm(true); setSolanaWizardStep(0); setSolanaPubkeyPreview(null); }}>
        Connect Solana wallet
      </button>
    </div>
  ) : null}

  {showSolanaForm && (
    <div className="sol-wizard">
      {/* Step indicators */}
      <div className="sol-wizard__steps">
        {["Import", "Verify", "RPC"].map((label, idx) => (
          <div key={idx} className={`sol-wizard__step ${solanaWizardStep >= idx ? "active" : ""} ${solanaWizardStep === idx ? "current" : ""}`}>
            <span className="sol-wizard__step-num">{idx + 1}</span>
            <span className="sol-wizard__step-label">{label}</span>
          </div>
        ))}
      </div>

      {/* Step 0: Import key */}
      {solanaWizardStep === 0 && (
        <div className="sol-wizard__panel">
          <h4 className="sol-wizard__heading">Import your wallet</h4>
          <p className="sol-wizard__text">Paste your base58 private key, or paste the contents of your <code>id.json</code> keyfile.</p>
          <div className="sol-wizard__input-wrap">
            <textarea
              className="sol-wizard__textarea"
              rows={3}
              value={solanaForm.privateKey}
              onChange={(e) => {
                let val = e.target.value.trim();
                // Auto-detect JSON array format (id.json) and convert
                if (val.startsWith("[") && val.endsWith("]")) {
                  try {
                    const arr = JSON.parse(val);
                    if (Array.isArray(arr) && arr.length === 64) {
                      // Convert byte array to base58
                      val = "__JSON_ARRAY__";
                      setSolanaForm((f) => ({ ...f, privateKey: val, _rawBytes: arr }));
                      return;
                    }
                  } catch {}
                }
                setSolanaForm((f) => ({ ...f, privateKey: val }));
              }}
              placeholder="Base58 private key or [byte array from id.json]"
              autoComplete="off"
              spellCheck={false}
            />
            <button
              type="button"
              className="sol-wizard__toggle-vis"
              onClick={() => setSolanaKeyVisible((v) => !v)}
              title={solanaKeyVisible ? "Hide" : "Show"}
            >{solanaKeyVisible ? "Hide" : "Show"}</button>
          </div>
          {!solanaKeyVisible && solanaForm.privateKey && solanaForm.privateKey !== "__JSON_ARRAY__" && (
            <p className="sol-wizard__masked">{solanaForm.privateKey.slice(0, 8)}{"•".repeat(20)}{solanaForm.privateKey.slice(-4)}</p>
          )}
          {solanaForm.privateKey === "__JSON_ARRAY__" && (
            <p className="sol-wizard__masked">JSON keyfile detected (64 bytes)</p>
          )}

          <div className="sol-wizard__security">
            <span className="sol-wizard__lock-icon">🔒</span>
            <span>Your key is encrypted with Fernet (AES-128-CBC) before storage. It never leaves the server and is decrypted only in memory during trade execution.</span>
          </div>

          <div className="sol-wizard__nav">
            <button type="button" className="sol-wizard__btn sol-wizard__btn--secondary" onClick={() => { setShowSolanaForm(false); setSolanaForm({ privateKey: "", rpcUrl: "" }); }}>Cancel</button>
            <button
              type="button"
              className="sol-wizard__btn sol-wizard__btn--primary"
              disabled={!solanaForm.privateKey}
              onClick={async () => {
                setSolanaPubkeyPreview(null);
                try {
                  const key = solanaForm.privateKey === "__JSON_ARRAY__"
                    ? solanaForm.privateKey  // server handles conversion
                    : solanaForm.privateKey;
                  const r = await api.verifySolanaKey(key);
                  if (r.valid) {
                    setSolanaPubkeyPreview(r.pubkey);
                    setSolanaWizardStep(1);
                  } else {
                    setSolanaStatus({ ok: false, msg: r.error || "Invalid key format" });
                  }
                } catch (err) {
                  setSolanaStatus({ ok: false, msg: err.message });
                }
              }}
            >Verify key →</button>
          </div>
        </div>
      )}

      {/* Step 1: Verify pubkey */}
      {solanaWizardStep === 1 && (
        <div className="sol-wizard__panel">
          <h4 className="sol-wizard__heading">Confirm your wallet</h4>
          <p className="sol-wizard__text">Make sure this is the wallet you want to trade with:</p>
          {solanaPubkeyPreview && (
            <div className="sol-wizard__pubkey-card">
              <span className="sol-wizard__pubkey-label">Wallet address</span>
              <span className="sol-wizard__pubkey-value">{solanaPubkeyPreview}</span>
              <a
                className="sol-wizard__explorer-link"
                href={`https://solscan.io/account/${solanaPubkeyPreview}`}
                target="_blank"
                rel="noopener noreferrer"
              >View on Solscan ↗</a>
            </div>
          )}
          <div className="sol-wizard__nav">
            <button type="button" className="sol-wizard__btn sol-wizard__btn--secondary" onClick={() => setSolanaWizardStep(0)}>← Back</button>
            <button type="button" className="sol-wizard__btn sol-wizard__btn--primary" onClick={() => setSolanaWizardStep(2)}>Confirm & continue →</button>
          </div>
        </div>
      )}

      {/* Step 2: RPC selection */}
      {solanaWizardStep === 2 && (
        <form className="sol-wizard__panel" onSubmit={handleSaveSolanaKeys}>
          <h4 className="sol-wizard__heading">Choose RPC endpoint</h4>
          <p className="sol-wizard__text">A dedicated RPC is recommended for reliable trade execution. The public endpoint works but may be rate-limited.</p>
          <div className="sol-wizard__rpc-options">
            {[
              { label: "Public (free)", url: "", desc: "Rate-limited, best for testing" },
              { label: "Helius", url: "https://mainnet.helius-rpc.com/?api-key=", desc: "Fast, reliable — get a free key at helius.dev" },
              { label: "QuickNode", url: "https://", desc: "Enterprise-grade — quicknode.com" },
              { label: "Custom", url: "__custom__", desc: "Paste any Solana RPC URL" },
            ].map((opt) => (
              <label key={opt.label} className={`sol-wizard__rpc-option ${solanaForm.rpcUrl === opt.url || (opt.url === "" && !solanaForm.rpcUrl) ? "active" : ""}`}>
                <input
                  type="radio"
                  name="rpc"
                  checked={opt.url === "__custom__"
                    ? ![""," https://mainnet.helius-rpc.com/?api-key=","https://"].includes(solanaForm.rpcUrl) && solanaForm.rpcUrl !== ""
                    : solanaForm.rpcUrl === opt.url || (opt.url === "" && !solanaForm.rpcUrl)}
                  onChange={() => setSolanaForm((f) => ({ ...f, rpcUrl: opt.url === "__custom__" ? (f.rpcUrl || "https://") : opt.url }))}
                />
                <div className="sol-wizard__rpc-label">
                  <span className="sol-wizard__rpc-name">{opt.label}</span>
                  <span className="sol-wizard__rpc-desc">{opt.desc}</span>
                </div>
              </label>
            ))}
          </div>
          {solanaForm.rpcUrl && solanaForm.rpcUrl !== "" && (
            <input
              className="sol-wizard__rpc-input"
              type="text"
              value={solanaForm.rpcUrl}
              onChange={(e) => setSolanaForm((f) => ({ ...f, rpcUrl: e.target.value }))}
              placeholder="https://your-rpc-endpoint.com"
            />
          )}
          <div className="sol-wizard__nav">
            <button type="button" className="sol-wizard__btn sol-wizard__btn--secondary" onClick={() => setSolanaWizardStep(1)}>← Back</button>
            <button type="submit" className="sol-wizard__btn sol-wizard__btn--primary" disabled={savingSolana}>
              {savingSolana ? "Connecting…" : "Connect wallet"}
            </button>
          </div>
        </form>
      )}

      {solanaStatus && (
        <p className={`trade-status ${solanaStatus.ok ? "trade-status--ok" : "trade-status--err"}`}>{solanaStatus.msg}</p>
      )}
    </div>
  )}
</div>

